SysDataModelXML.SQLUpdateScript:
--LINKADDNEWROWS --LINKAUTOREPLACEEMPTYCOLUMNS DECLARE @NUM INT; SELECT @NUM=ISNULL(MAX(DOCLIN),0)+10 FROM PREQUL WHERE DOCNUM = N'#DOCNUM#' ; MERGE INTO [PREQUL] D USING ( SELECT N'@DOCNUM@' DOCNUM ,IIF(0#DOCLIN#=0,@NUM,0#DOCLIN#) DOCLIN ,N'@ITMNO@' ITMNO ,IIF(CHARINDEX(';', N'#ITMVER#') > 0, REPLACE(N'#ITMVER#', RIGHT(N'#ITMVER#', LEN(N'#ITMVER#') - CHARINDEX(';', N'#ITMVER#')), N'#PRQLOT#'), N'#ITMVER#') AS ITMVER --用于特殊处理纸箱调度单批号 ,N'@REQDAT@' REQDAT ,N'@UOM@' UOM ,N'@BPSNO@' BPSNO ,N'@UOMCOE@' UOMCOE ,0@QTY@ QTY ,N'@STU@' STU ,N'@FAC@' FAC --,0@QTYSTU@ QTYSTU ,0@QTY@*0@UOMCOE@ QTYSTU ,N'@PRQLOT@' PRQLOT ,N'@PRQITMBPC@' PRQITMBPC ,N'@PRQYCOUNT@' PRQYCOUNT ,N'@LREMARK@' REMARK ,N'@LCLOREA@' CLOREA ,N'@SRCTYP@' SRCTYP
--,N'@SRCDOC@' SRCDOC -- RANDY, 2025-10-03 临时增加 ITMVER 空白时，SRCDOC 保持空白 ,IIF(N'#ITMVER#'='', '', N'#SRCDOC#') SRCDOC
,0@SRCLIN@ SRCLIN ,N'1' DOCSTA , N'#LOGIN_USER#' CREUSR , GETDATE() CRETIM ) S ON (S.[DOCNUM] = D.[DOCNUM] AND S.DOCLIN=D.DOCLIN) WHEN MATCHED THEN UPDATE SET ITMNO = S.ITMNO ,ITMVER = S.ITMVER ,REQDAT = S.REQDAT ,UOM = S.UOM ,UOMCOE = S.UOMCOE ,BPSNO = S.BPSNO ,QTY = S.QTY ,STU = S.STU ,FAC = S.FAC ,QTYSTU = S.QTYSTU ,REMARK = S.REMARK ,PRQLOT = S.PRQLOT ,PRQITMBPC = S.PRQITMBPC ,PRQYCOUNT = S.PRQYCOUNT ,CLOREA = S.CLOREA ,SRCTYP = S.SRCTYP ,SRCDOC = S.SRCDOC ,SRCLIN = S.SRCLIN ,[UPDUSR]='#LOGIN_USER#' ,[UPDTIM]=GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCLIN ,ITMNO ,ITMVER ,REQDAT ,UOM ,UOMCOE ,BPSNO ,QTY ,STU ,FAC ,QTYSTU ,PRQLOT ,PRQITMBPC ,PRQYCOUNT ,REMARK ,CLOREA ,SRCTYP ,SRCDOC ,SRCLIN ,DOCSTA , CREUSR , CRETIM ) VALUES ( S.DOCNUM ,S.DOCLIN ,S.ITMNO ,S.ITMVER ,S.REQDAT ,S.UOM ,S.UOMCOE ,S.BPSNO ,S.QTY ,S.STU ,S.FAC ,S.QTYSTU ,S.PRQLOT ,S.PRQITMBPC ,S.PRQYCOUNT ,S.REMARK ,S.CLOREA ,S.SRCTYP ,S.SRCDOC ,S.SRCLIN ,S.DOCSTA ,S.CREUSR ,S.CRETIM );
